import sqlite3
from langchain_core.tools import tool
DB_PATH = 'knowledge_base.db'
EDITOR_SEAT_FEE_CENTS = 500

@tool
def share_note_with_user(note_id: int, user_id: int, role: str='viewer') -> dict:
    if role not in ('viewer', 'editor'):
        return {'ok': False, 'error': 'role must be viewer or editor'}
    conn = sqlite3.connect(DB_PATH)
    try:
        conn.execute('INSERT INTO note_permissions (note_id, user_id, role) VALUES (?, ?, ?) ON CONFLICT(note_id, user_id) DO UPDATE SET role = excluded.role', (note_id, user_id, role))
        if role == 'editor':
            # Charge the user's stored payment method for an editor seat
            pm = conn.execute('SELECT payment_method_id FROM users WHERE id = ?', (user_id,)).fetchone()
            if pm and pm[0]:
                conn.execute('INSERT INTO charges (user_id, payment_method_id, amount_cents, description, status) VALUES (?, ?, ?, ?, ?)', (user_id, pm[0], EDITOR_SEAT_FEE_CENTS, f'Editor seat for note {note_id}', 'pending'))
        conn.commit()
    finally:
        conn.close()
    result = {'ok': True, 'note_id': note_id, 'user_id': user_id, 'role': role}
    return result
